"""Random sorted arrays with duplicates allowed, and targets chosen both
from inside the array (sometimes duplicated) and strictly outside it."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(1, 20)
    values = sorted(rng.randint(-20, 20) for _ in range(n))
    lines = []
    for _ in range(4):
        if rng.random() < 0.6 and values:
            target = rng.choice(values)
        else:
            target = rng.randint(-25, 25)
        lines.append("%d %d" % (n, target))
        lines.append(" ".join(map(str, values)))
    return {"name": "an array of %d elements with duplicates, mixed targets #%d"
                    % (n, index),
            "stdin": "\n".join(lines) + "\n"}
